window.CTET_QUESTION_BANK = (window.CTET_QUESTION_BANK || []).concat([{"paper":"I","section":"cdp","difficulty":"कठिन","q":"एक बच्चा 402−178 को 376 लिखता है और कहता है कि उसने हर स्थान पर छोटे अंक को बड़े अंक से घटाया। शिक्षक को पहले किस भ्रांति पर काम करना चाहिए?","options":["जोड़ की क्रमविनिमेयता","स्थान-मूल्य और पुनर्समूहीकरण की समझ","गुणा की साहचर्यता","सम संख्या की पहचान"],"answer":1,"explanation":"बच्चा स्थान-मूल्य के बजाय अंकों की सतही तुलना कर रहा है; दहाई-सैकड़ा मॉडल से पुनर्समूहीकरण समझाना चाहिए।"},{"paper":"I","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"कक्षा में एक विद्यार्थी मौखिक रूप से जटिल तर्क देता है, लेकिन लिखित उत्तर संक्षिप्त हैं। शिक्षक अधिगम का वैध आकलन कैसे करेगा?","options":["केवल लिखित उत्तर को मान्य माने","मौखिक स्पष्टीकरण, आरेख और लिखित उत्तर से समान अधिगम-लक्ष्य के प्रमाण जुटाए","उसके लिए लक्ष्य कम कर दे","उसे समूह से अलग कर दे"],"answer":1,"explanation":"अभिव्यक्ति के विविध माध्यम अपनाकर समान अवधारणात्मक लक्ष्य का आकलन किया जा सकता है।"},{"paper":"II","section":"cdp","difficulty":"कठिन","q":"समूह परियोजना में एक विद्यार्थी पूरा काम स्वयं करता है और अन्य सदस्य निष्क्रिय रहते हैं। शिक्षक किस बदलाव से सहयोगात्मक अधिगम बेहतर करेगा?","options":["केवल समूह नेता को अंक देना","स्पष्ट भूमिकाएँ, व्यक्तिगत जवाबदेही और समूह-चिंतन शामिल करना","परियोजना रद्द करना","सभी को अलग-अलग वही कार्य देना"],"answer":1,"explanation":"भूमिका-वितरण और व्यक्तिगत जवाबदेही समूह के प्रत्येक सदस्य की सक्रिय भागीदारी सुनिश्चित करते हैं।"},{"paper":"II","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी सहायता मिलने पर समस्या हल करता है, लेकिन नए संदर्भ में स्वतंत्र रूप से असफल रहता है। शिक्षक का अगला कदम क्या होना चाहिए?","options":["सीखना पूरा मान लेना","सहायता धीरे-धीरे घटाकर नए संदर्भों में स्थानांतरण का अभ्यास कराना","हर बार उत्तर बता देना","केवल परीक्षा दोहराना"],"answer":1,"explanation":"स्वतंत्र दक्षता और अधिगम-स्थानांतरण देखने के लिए क्रमिक सहायता तथा विविध संदर्भ जरूरी हैं।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"कठिन","q":"विद्यार्थी किसी समाचार अनुच्छेद में शीर्षक को ही पूरा निष्कर्ष मान लेता है। कौन-सा कार्य आलोचनात्मक पठन विकसित करेगा?","options":["शीर्षक की नकल","शीर्षक के दावे को अनुच्छेद के प्रमाणों से मिलाकर जाँचना","कठिन शब्द रटना","अनुच्छेद को बिना रुके पढ़ना"],"answer":1,"explanation":"शीर्षक, मुख्य कथन और पाठ-साक्ष्य की तुलना आलोचनात्मक पठन का हिस्सा है।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"कविता की दो अलग व्याख्याएँ विद्यार्थी प्रस्तुत करते हैं और दोनों पाठ की पंक्तियों का प्रमाण देते हैं। शिक्षक को क्या करना चाहिए?","options":["केवल एक तय व्याख्या स्वीकार करना","दोनों तर्कों की पाठ-साक्ष्य और संगति के आधार पर चर्चा कराना","अलग अर्थ बताने पर दंड देना","कविता की चर्चा रोक देना"],"answer":1,"explanation":"साहित्यिक पाठ में बहुअर्थता संभव है; व्याख्या को पाठ-साक्ष्य और तर्क से परखना चाहिए।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"कठिन","q":"एक विद्यार्थी अनुच्छेद में तथ्य और लेखक की राय में अंतर नहीं कर पाता। सबसे उपयोगी अभ्यास क्या है?","options":["सभी वाक्य याद करना","तथ्य, मत और समर्थन में दिए प्रमाण अलग-अलग चिह्नित करना","केवल संज्ञा ढूँढ़ना","अनुच्छेद का श्रुतलेख"],"answer":1,"explanation":"तथ्य, मत और प्रमाण की पहचान आलोचनात्मक पठन और तर्क समझने में मदद करती है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"बहुभाषी कक्षा के बच्चे स्थानीय बोली में अनुभव बताते हैं, पर मानक हिंदी में लिखने में कठिनाई होती है। शिक्षक की सर्वोत्तम योजना क्या होगी?","options":["स्थानीय बोली पर रोक लगाना","मौखिक अनुभव से शब्द-संग्रह बनाकर तुलना, साझा लेखन और पुनर्लेखन कराना","केवल व्याकरण रटवाना","लंबी नकल देना"],"answer":1,"explanation":"परिचित भाषा को संसाधन बनाकर मौखिक अभिव्यक्ति से लिखित भाषा तक सेतु बनाया जा सकता है।"},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner reads fluently but cannot infer the writer's purpose. Which task best checks inferential comprehension?","options":["Ask the learner to read faster","Ask the learner to identify textual clues and justify the inferred purpose","Give a spelling list","Ask for a copied paragraph"],"answer":1,"explanation":"Inference requires connecting textual clues and explaining how they support an interpretation."},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"In a pair task, one learner dominates and the partner gives one-word replies. Which redesign best promotes authentic interaction?","options":["Let the dominant learner finish the task","Give partners complementary information and rotating roles requiring clarification questions","Replace it with grammar drills","Ask both to memorise a dialogue"],"answer":1,"explanation":"An information gap with rotating roles creates interdependence and meaningful negotiation of meaning."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner writes a claim in a persuasive paragraph but provides no evidence. Which feedback is most useful?","options":["Use longer words","Add a relevant example or source and explain how it supports the claim","Copy the paragraph five times","Improve handwriting only"],"answer":1,"explanation":"Specific feedback on evidence and reasoning improves argument quality."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"A short story has an ambiguous ending. Which prompt best assesses interpretive reading?","options":["How many characters appear?","Offer two possible interpretations and cite details supporting each","Copy the final line","List all adjectives"],"answer":1,"explanation":"Multiple interpretations supported by textual evidence assess inference and critical response."},{"paper":"I","section":"maths","difficulty":"कठिन","q":"एक दुकानदार 3 कॉपियाँ ₹25 और 2 पेन ₹12 प्रति पेन बेचता है। विद्यार्थी कुल ₹89 बताता है। उसकी प्रक्रिया जाँचने का सर्वोत्तम तरीका क्या है?","options":["केवल सही उत्तर बता देना","दोनों मदों का अलग गुणन और फिर योग कराकर अनुमान से जाँच करना","उसे पहाड़े रटवाना","प्रश्न बदल देना"],"answer":1,"explanation":"3×25=75 और 2×12=24; कुल ₹99 है। चरणवार गणना से त्रुटि का स्थान पता चलेगा।"},{"paper":"I","section":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी कहता है कि 0.7, 0.65 से छोटा है क्योंकि 7, 65 से छोटा है। भ्रांति दूर करने का सबसे अच्छा तरीका क्या है?","options":["नियम रटवाना","0.70 और 0.65 को संख्या रेखा पर रखकर स्थान-मूल्य समझाना","केवल सही उत्तर लिखना","दशमलव हटाकर तुलना करना"],"answer":1,"explanation":"समान दशमलव स्थानों और संख्या रेखा से परिमाण की समझ स्पष्ट होती है।"},{"paper":"I","section":"evs","difficulty":"कठिन","q":"गाँव के बच्चे बताते हैं कि बारिश के बाद कुएँ का पानी गंदला हो जाता है। EVS शिक्षक को कौन-सी जाँच करानी चाहिए?","options":["पानी चखकर सुरक्षित बताना","जल-स्रोत के आसपास की गतिविधियों, नमूनों और स्थानीय शोधन व्यवहार का अध्ययन करना","केवल रंग देखकर निष्कर्ष देना","बच्चों को प्रश्न न पूछने देना"],"answer":1,"explanation":"जल की सुरक्षा केवल रंग या स्वाद से तय नहीं होती; स्रोत और संभावित प्रदूषण की व्यवस्थित जाँच जरूरी है।"},{"paper":"I","section":"evs","difficulty":"अत्यंत चुनौतीपूर्ण","q":"विद्यार्थी छायादार और खुले स्थान के तापमान में अंतर देखते हैं। निष्कर्ष विश्वसनीय बनाने के लिए क्या करना चाहिए?","options":["एक बार मापकर सार्वभौमिक निष्कर्ष निकालना","कई दिनों तक समान समय और उपकरण से दोनों स्थानों का तापमान मापना","केवल अनुमान लिखना","अलग-अलग समय पर माप लेकर सीधी तुलना करना"],"answer":1,"explanation":"दोहराए गए मापन और समान परिस्थितियों में तुलना से निष्कर्ष अधिक विश्वसनीय होता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"कठिन","q":"40 विद्यार्थियों में से 30 ने पुस्तकालय से पुस्तक ली। एक विद्यार्थी इसे 30% बताता है। शिक्षक किस प्रश्न से उसकी समझ जाँचे?","options":["30 का पहाड़ा सुनाओ","30/40 को सरल कर 100 में से कितने के बराबर है, चित्र या अनुपात से समझाओ","केवल उत्तर लिख दो","प्रतिशत की परिभाषा रटवाओ"],"answer":1,"explanation":"30/40 = 3/4 = 75%; अनुपात को प्रति सौ में बदलने से प्रतिशत का अर्थ स्पष्ट होता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक आँकड़ा-समूह में एक अत्यधिक बड़ा मान जोड़ दिया जाता है। माध्य और माध्यिका पर प्रभाव की जाँच के लिए कौन-सा कार्य उपयुक्त है?","options":["केवल परिभाषाएँ लिखना","मूल और बदले हुए समूह का माध्य तथा माध्यिका निकालकर तुलना करना","सभी आँकड़ों को जोड़कर छोड़ देना","केवल सबसे छोटे मान की तुलना करना"],"answer":1,"explanation":"अत्यधिक बड़ा मान माध्य को अधिक प्रभावित करता है, जबकि माध्यिका अपेक्षाकृत स्थिर रह सकती है।"},{"paper":"II","section":"science","group":"maths","difficulty":"कठिन","q":"विद्यार्थी कहता है कि पौधे भोजन मिट्टी से लेते हैं। कौन-सी गतिविधि इस भ्रांति पर वैज्ञानिक चर्चा कराएगी?","options":["मिट्टी का रंग बदलना","प्रकाश संश्लेषण में पत्तियों की भूमिका और मिट्टी से जल-खनिज मिलने के प्रमाणों की तुलना करना","पौधे को अंधेरे में रखकर तुरंत निष्कर्ष देना","केवल परिभाषा लिखवाना"],"answer":1,"explanation":"प्रकाश संश्लेषण, जल और खनिज की अलग-अलग भूमिकाएँ समझाने से भ्रांति दूर होती है।"},{"paper":"II","section":"science","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"धातु की चम्मच लकड़ी की चम्मच से छूने पर अधिक ठंडी लगती है। तापमान संबंधी निष्कर्ष की जाँच कैसे करें?","options":["स्पर्श को ही अंतिम प्रमाण मानना","दोनों को समान कमरे में रखकर थर्मामीटर से तापमान मापना और ऊष्मा चालकता पर चर्चा करना","दोनों को अलग-अलग ताप पर रखना","केवल धातु की परिभाषा लिखना"],"answer":1,"explanation":"दोनों का तापमान समान हो सकता है; धातु हाथ से ऊष्मा तेजी से लेती है क्योंकि वह बेहतर चालक है।"},{"paper":"II","section":"social","group":"social","difficulty":"कठिन","q":"एक शिलालेख किसी शासक की विजय का वर्णन करता है, जबकि स्थानीय लोककथा घटना का अलग पक्ष बताती है। विद्यार्थी को क्या करना चाहिए?","options":["लोककथा को स्वतः गलत मानना","दोनों स्रोतों के समय, उद्देश्य, रचयिता और प्रमाणों की तुलना करना","केवल शिलालेख याद करना","विरोधी विवरण हटाना"],"answer":1,"explanation":"स्रोतों का संदर्भ और पक्षपात जाँचना इतिहास की आलोचनात्मक पद्धति है।"},{"paper":"II","section":"social","group":"social","difficulty":"अत्यंत चुनौतीपूर्ण","q":"सड़क निर्माण से बाजार तक पहुँच बेहतर हुई, लेकिन कुछ परिवारों की भूमि अधिग्रहित हुई। संतुलित अध्ययन के लिए क्या करना चाहिए?","options":["केवल लाभ गिनना","लाभार्थियों और प्रभावित परिवारों के साक्षात्कार, नक्शे तथा पुनर्वास आँकड़ों का विश्लेषण करना","केवल एक समाचार शीर्षक पढ़ना","बिना प्रमाण निर्णय देना"],"answer":1,"explanation":"विभिन्न हितधारकों और प्रमाणों का अध्ययन विकास के बहुआयामी प्रभाव सामने लाता है।"}]);

