window.CTET_QUESTION_BANK = (window.CTET_QUESTION_BANK || []).concat([{"paper":"I","section":"cdp","difficulty":"कठिन","q":"एक बच्चा 3/5 को 3/7 से छोटा बताता है क्योंकि 5, 7 से छोटा है। शिक्षक कौन-सा तरीका अपनाए?","options":["केवल सही उत्तर लिखवाना","समान अंश वाले भिन्नों को चित्र और संख्या रेखा पर दिखाकर परिमाण की तुलना कराना","हरों को जोड़ना सिखाना","गलती को लापरवाही मानना"],"answer":1,"explanation":"समान अंश होने पर हर बड़ा होने से प्रत्येक भाग छोटा होता है; दृश्य निरूपण से यह स्पष्ट होगा।"},{"paper":"I","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी नई समस्या को हल करने के लिए पुरानी रणनीति अपनाता है, पर असफल होने पर स्वयं रणनीति बदलता है। यह किसका सबसे अच्छा उदाहरण है?","options":["यांत्रिक अनुकरण","मेटाकॉग्निटिव निगरानी और रणनीति-नियमन","बाह्य अभिप्रेरणा","केवल स्मृति"],"answer":1,"explanation":"अपनी रणनीति की प्रभावशीलता पर विचार करके उसे बदलना मेटाकॉग्निशन का हिस्सा है।"},{"paper":"I","section":"cdp","difficulty":"कठिन","q":"शिक्षक ने एक ही अवधारणा के लिए चित्र, वस्तु, चर्चा और लिखित अभ्यास दिए। इसका प्रमुख शैक्षिक आधार क्या है?","options":["सभी बच्चों की क्षमता समान होती है","विविध निरूपण अलग-अलग पूर्वज्ञान और सीखने की आवश्यकताओं को सहारा देते हैं","चित्र हमेशा लिखित कार्य से बेहतर हैं","मूल्यांकन की आवश्यकता नहीं रहती"],"answer":1,"explanation":"बहुविध निरूपण से विद्यार्थी अवधारणा को अलग संदर्भों में समझ और व्यक्त कर सकते हैं।"},{"paper":"II","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी कक्षा में सही उत्तर देता है, पर कारण पूछने पर अपनी बात बदल देता है। शिक्षक को किस आधार पर उपलब्धि दर्ज करनी चाहिए?","options":["पहले उत्तर को पूर्ण समझ मानना","व्याख्या, नए उदाहरण और स्वतंत्र अनुप्रयोग के प्रमाण लेकर वैचारिक समझ जाँचना","केवल गति को अंक देना","उसे उत्तर याद करने को कहना"],"answer":1,"explanation":"अवधारणा की गहरी समझ तर्क और नए संदर्भ में अनुप्रयोग से बेहतर जाँची जाती है।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"कठिन","q":"एक विद्यार्थी कहानी के अंत का अनुमान सही लगाता है, लेकिन पाठ से कोई संकेत नहीं बता पाता। शिक्षक क्या पूछे?","options":["कहानी कितने पृष्ठ की है?","कौन-से शब्द, घटनाएँ या पात्रों के व्यवहार ने तुम्हें इस निष्कर्ष तक पहुँचाया?","कहानी फिर से नकल करो","लेखक का नाम बताओ"],"answer":1,"explanation":"अनुमान को पाठ-साक्ष्य से जोड़ना निष्कर्षात्मक पठन का आवश्यक भाग है।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"किसी लेख में लेखक आँकड़े देता है, पर उनसे निकाला गया निष्कर्ष आँकड़ों से पूरी तरह समर्थित नहीं है। विद्यार्थी को क्या करना चाहिए?","options":["लेखक की बात बिना जाँच स्वीकार करना","दिए गए आँकड़ों और निष्कर्ष के बीच तार्किक संबंध की जाँच करना","केवल आँकड़े याद करना","शीर्षक बदल देना"],"answer":1,"explanation":"आँकड़ों की पर्याप्तता और निष्कर्ष की तार्किक वैधता जाँचना आलोचनात्मक पठन है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"कठिन","q":"विद्यार्थी किसी अनुच्छेद का सार लिखते समय लगभग हर वाक्य की नकल करता है। कौन-सी रणनीति उपयोगी होगी?","options":["और लंबा अनुच्छेद देना","मुख्य विचार, सहायक विवरण और अनावश्यक उदाहरण अलग करवाकर अपने शब्दों में सार लिखवाना","केवल सुंदर लिखावट का अभ्यास","शब्दों की वर्णमाला बनवाना"],"answer":1,"explanation":"सार-लेखन में मुख्य विचार चुनना और गौण विवरण हटाना आवश्यक है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक पाठ में किसी समुदाय का चित्रण रूढ़िबद्ध है। उच्चतर पठन-बोध के लिए शिक्षक कौन-सा प्रश्न पूछे?","options":["पाठ में कितने अनुच्छेद हैं?","किसका दृष्टिकोण प्रस्तुत है, किसकी आवाज अनुपस्थित है और पाठक पर इसका क्या प्रभाव पड़ सकता है?","कठिन शब्द कितने हैं?","लेखक का नाम क्या है?"],"answer":1,"explanation":"दृष्टिकोण, प्रतिनिधित्व और अनुपस्थित आवाजों का विश्लेषण आलोचनात्मक साक्षरता विकसित करता है।"},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner chooses a correct option in a comprehension test but cannot explain it. What should the teacher do to check understanding?","options":["Assume mastery from the selected option","Ask the learner to point to textual evidence and explain the reasoning","Give more spelling tests","Ask the learner to memorise the answer"],"answer":1,"explanation":"Textual evidence and reasoning help distinguish genuine comprehension from guessing."},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"Two learners interpret a character's silence differently, each citing details from the story. What is the most appropriate classroom response?","options":["Accept only the teacher's interpretation","Compare both interpretations against textual evidence and context","Stop the discussion","Mark both wrong because they differ"],"answer":1,"explanation":"Interpretive reading allows reasoned alternatives when they are supported by textual evidence."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner's paragraph has ideas in random order. Which feedback best supports coherence?","options":["Use difficult vocabulary","Group related ideas and add linking expressions to show their relationship","Make every sentence longer","Copy a model paragraph"],"answer":1,"explanation":"Logical grouping and cohesive devices improve the flow and coherence of writing."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"A class compares two short reports describing the same event but emphasizing different details. Which task best develops media literacy?","options":["Count the sentences in each report","Identify selection, omission, language choices and whose perspective each report foregrounds","Memorise both headlines","Choose the longer report as more reliable"],"answer":1,"explanation":"Media literacy involves examining framing, omission, language and perspective rather than length."},{"paper":"I","section":"maths","difficulty":"कठिन","q":"एक दुकानदार किसी वस्तु का मूल्य ₹800 से बढ़ाकर ₹1,000 करता है। विद्यार्थी वृद्धि को 20% बताता है। शिक्षक उसकी समझ कैसे जाँचे?","options":["केवल सही प्रतिशत बताए","वृद्धि ₹200 को मूल मूल्य ₹800 के सापेक्ष रखकर प्रतिशत का अर्थ समझाने को कहे","नए मूल्य को आधार माने","केवल सूत्र रटवाए"],"answer":1,"explanation":"प्रतिशत परिवर्तन का आधार मूल मूल्य है; 200/800 × 100 = 25%।"},{"paper":"I","section":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक आयत की लंबाई 20% बढ़ाई और चौड़ाई 20% घटाई जाती है। क्षेत्रफल के बारे में सही निष्कर्ष क्या है?","options":["क्षेत्रफल अपरिवर्तित रहेगा","क्षेत्रफल 4% घटेगा","क्षेत्रफल 4% बढ़ेगा","क्षेत्रफल 20% घटेगा"],"answer":1,"explanation":"नया गुणक 1.2 × 0.8 = 0.96 है, इसलिए क्षेत्रफल 4% घटता है।"},{"paper":"I","section":"evs","difficulty":"कठिन","q":"विद्यार्थी दावा करते हैं कि किसी पौधे की वृद्धि केवल पानी की मात्रा पर निर्भर करती है। शिक्षक निष्पक्ष जाँच कैसे कराए?","options":["हर पौधे को अलग-अलग मिट्टी और प्रकाश देना","समान पौधों में एक समय पर केवल पानी की मात्रा बदलकर बाकी स्थितियाँ समान रखना","एक पौधे का अवलोकन कर निष्कर्ष निकालना","बच्चों से दावा याद करवाना"],"answer":1,"explanation":"एक चर बदलकर अन्य स्थितियाँ समान रखने से कारण-प्रभाव की जाँच अधिक उचित होती है।"},{"paper":"I","section":"evs","difficulty":"अत्यंत चुनौतीपूर्ण","q":"किसी बस्ती में डेंगू के मामले बढ़े हैं। विद्यार्थी कारणों की जाँच करना चाहते हैं। कौन-सी गतिविधि उपयुक्त और सुरक्षित है?","options":["बिना अनुमति घरों में प्रवेश करना","स्थानीय स्वास्थ्यकर्मी से जानकारी लेकर सुरक्षित रूप से जल-जमाव स्थलों का अवलोकन और रोकथाम उपायों का अध्ययन करना","मच्छरों को हाथ से पकड़ना","केवल अफवाहों के आधार पर निष्कर्ष देना"],"answer":1,"explanation":"स्थानीय प्रमाण, स्वास्थ्यकर्मी का मार्गदर्शन और सुरक्षित अवलोकन जिम्मेदार पर्यावरणीय जाँच है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"कठिन","q":"एक विद्यार्थी 2(x+3)=2x+3 लिखता है। शिक्षक किस गतिविधि से वितरण नियम की भ्रांति दूर कर सकता है?","options":["केवल नियम लिखवाना","x के किसी मान को रखकर दोनों व्यंजकों का मान तुलना कराना और क्षेत्र-मॉडल दिखाना","गलत उत्तर काट देना","अगला अध्याय शुरू करना"],"answer":1,"explanation":"संख्यात्मक उदाहरण और दृश्य मॉडल से गुणन का दोनों पदों पर वितरण स्पष्ट होता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक सर्वेक्षण में 60% विद्यार्थियों ने खेल A और 50% ने खेल B चुना। कुछ विद्यार्थियों ने दोनों चुने। केवल इन प्रतिशतों से क्या निष्कर्ष निकाला जा सकता है?","options":["दोनों चुनने वाले ठीक 10% हैं","दोनों चुनने वालों की संख्या निश्चित नहीं; अतिरिक्त जानकारी चाहिए","किसी ने दोनों नहीं चुने","कुल 110% विद्यार्थी हैं"],"answer":1,"explanation":"समुच्चय के प्रतिच्छेद की जानकारी के बिना दोनों चुनने वालों का सटीक प्रतिशत नहीं निकाला जा सकता।"},{"paper":"II","section":"science","group":"maths","difficulty":"कठिन","q":"विद्यार्थी कहता है कि गर्म पानी में चीनी इसलिए जल्दी घुलती है क्योंकि गर्म पानी में चीनी का स्वाद मीठा हो जाता है। शिक्षक किस जाँच का सुझाव दे?","options":["अलग-अलग मात्रा की चीनी और पानी लें","समान मात्रा के पानी और चीनी को अलग ताप पर रखकर घुलने का समय नियंत्रित ढंग से तुलना करें","केवल स्वाद चखकर निष्कर्ष दें","एक ही बार परिणाम देखकर नियम बना दें"],"answer":1,"explanation":"नियंत्रित तुलना से तापमान का घुलने की दर पर प्रभाव जाँचा जा सकता है।"},{"paper":"II","section":"science","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी दावा करता है कि पौधे रात में श्वसन नहीं करते। इस दावे पर वैज्ञानिक चर्चा का सबसे सही आधार क्या है?","options":["पौधे केवल दिन में जीवित रहते हैं","प्रकाश संश्लेषण प्रकाश पर निर्भर है, जबकि कोशिकीय श्वसन दिन और रात दोनों समय होता है","रात में पौधों में कोई प्रक्रिया नहीं होती","केवल पत्तियों का रंग देखकर निर्णय लें"],"answer":1,"explanation":"प्रकाश संश्लेषण और श्वसन अलग प्रक्रियाएँ हैं; श्वसन ऊर्जा-मुक्ति के लिए लगातार होता है।"},{"paper":"II","section":"social","group":"social","difficulty":"कठिन","q":"किसी ऐतिहासिक घटना के लिए पाठ्यपुस्तक, सरकारी अभिलेख और मौखिक इतिहास में अलग विवरण मिलते हैं। विद्यार्थी को निष्कर्ष कैसे बनाना चाहिए?","options":["केवल पाठ्यपुस्तक को अंतिम माने","स्रोतों की प्रकृति, समय, उद्देश्य और पक्षपात की जाँच कर प्रमाणों का मिलान करे","सबसे लंबा विवरण चुने","असहमति वाले स्रोत हटा दे"],"answer":1,"explanation":"ऐतिहासिक निष्कर्ष बहु-स्रोत प्रमाणों की आलोचनात्मक तुलना से बनते हैं।"},{"paper":"II","section":"social","group":"social","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक जिले में खनन से रोजगार बढ़ा है, लेकिन जल-स्रोत प्रभावित हुए हैं। सामाजिक विज्ञान में संतुलित नीति-विश्लेषण के लिए क्या करना चाहिए?","options":["केवल रोजगार के आँकड़े देखना","आर्थिक लाभ, पर्यावरणीय लागत, प्रभावित समुदायों और नियामक विकल्पों के प्रमाणों की तुलना करना","केवल एक पक्ष का साक्षात्कार लेना","बिना प्रमाण खनन का समर्थन या विरोध करना"],"answer":1,"explanation":"नीति-विश्लेषण में आर्थिक, सामाजिक और पर्यावरणीय प्रभावों को साथ देखना आवश्यक है।"}]);

