window.CTET_QUESTION_BANK = (window.CTET_QUESTION_BANK || []).concat([{"paper":"I","section":"cdp","difficulty":"कठिन","q":"एक विद्यार्थी किसी नियम को अलग-अलग उदाहरणों में लागू कर लेता है, लेकिन अपवाद वाले उदाहरण में असफल होता है। शिक्षक को किस प्रकार का प्रश्न देना चाहिए?","options":["उसी उदाहरण को दोहराना","ऐसा नया उदाहरण देना जिसमें नियम की सीमा और अपवाद पहचानना पड़े","केवल परिभाषा लिखवाना","उसे अधिक तेज उत्तर देने को कहना"],"answer":1,"explanation":"नए और अपवाद वाले संदर्भ में प्रयोग से अवधारणा की गहराई और सीमाओं की समझ जाँची जाती है।"},{"paper":"I","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक कक्षा में विद्यार्थी अलग-अलग गति से सीखते हैं। शिक्षक समान अधिगम-लक्ष्य रखते हुए चुनौती और सहयोग दोनों कैसे सुनिश्चित कर सकता है?","options":["सभी को समान कार्य और समान सहायता देना","लचीले समूह, स्तरानुसार सहारा और विस्तार कार्य उपलब्ध कराना","धीमे सीखने वालों के लक्ष्य घटाना","तेज विद्यार्थियों को ही अतिरिक्त अवसर देना"],"answer":1,"explanation":"विभेदित शिक्षण में लक्ष्य साझा रहते हैं, पर सहायता और कार्य की जटिलता आवश्यकतानुसार बदल सकती है।"},{"paper":"II","section":"cdp","difficulty":"कठिन","q":"एक विद्यार्थी कहता है कि वह विज्ञान में अच्छा नहीं है क्योंकि वह प्रयोग में पहली बार असफल हुआ। शिक्षक की कौन-सी प्रतिक्रिया सबसे उपयोगी होगी?","options":["प्रयोग छोड़ दो","परिणाम की जाँच करो, चर पहचानो और संशोधित प्रक्रिया के साथ दोबारा प्रयास करो","दूसरे विद्यार्थी से उत्तर नकल करो","केवल सही परिणाम याद करो"],"answer":1,"explanation":"त्रुटि विश्लेषण, संशोधन और पुनः परीक्षण वैज्ञानिक दृष्टिकोण तथा विकासशील मानसिकता को बढ़ाते हैं।"},{"paper":"II","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक छात्र समूह परियोजना में सही निष्कर्ष तक पहुँचता है, पर समूह के एक सदस्य ने लगभग कोई योगदान नहीं दिया। शिक्षक निष्पक्ष मूल्यांकन कैसे करे?","options":["सभी को बिना जाँच समान व्यक्तिगत अंक दे","समूह उत्पाद के साथ व्यक्तिगत जर्नल, भूमिका और मौखिक स्पष्टीकरण के प्रमाण भी देखे","केवल समूह नेता को अंक दे","परियोजना के अंक रद्द कर दे"],"answer":1,"explanation":"समूह उत्पाद और व्यक्तिगत योगदान के अलग-अलग प्रमाण सहयोग तथा व्यक्तिगत जवाबदेही दोनों का आकलन करते हैं।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"कठिन","q":"विद्यार्थी किसी गद्यांश का निष्कर्ष निकालता है, लेकिन निष्कर्ष पाठ में सीधे लिखा नहीं है। शिक्षक किस आधार पर उत्तर को स्वीकार करे?","options":["केवल तभी जब शब्दशः वाक्य मौजूद हो","यदि विद्यार्थी पाठ के संकेतों और तर्क से निष्कर्ष का समर्थन करे","यदि उत्तर शिक्षक के शब्दों जैसा हो","यदि विद्यार्थी सबसे पहले उत्तर दे"],"answer":1,"explanation":"अनुमानात्मक पठन में निष्कर्ष प्रत्यक्ष रूप से लिखा न हो, फिर भी पाठ-साक्ष्य से समर्थित होना चाहिए।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक लेख में लेखक ने किसी समस्या के केवल एक पक्ष के आँकड़े दिए हैं। विद्यार्थी की आलोचनात्मक समझ जाँचने के लिए कौन-सा प्रश्न सबसे उपयुक्त है?","options":["लेख में कितने आँकड़े हैं?","कौन-सी अतिरिक्त जानकारी या वैकल्पिक दृष्टिकोण निष्कर्ष को बदल सकता है?","लेख का शीर्षक लिखो","सभी संख्याएँ याद करो"],"answer":1,"explanation":"चयनित प्रमाणों और अनुपस्थित दृष्टिकोणों की पहचान आलोचनात्मक साक्षरता का हिस्सा है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"कठिन","q":"एक विद्यार्थी किसी कविता का भावार्थ लिखते समय केवल पंक्तियों का सरल अर्थ देता है। भाव-बोध को गहरा करने के लिए शिक्षक क्या पूछे?","options":["कविता में कितने शब्द हैं?","कवि ने प्रयुक्त बिंब और भाषा से कौन-सा भाव उत्पन्न किया है?","कविता कितनी लंबी है?","कठिन शब्दों की नकल करो"],"answer":1,"explanation":"बिंब, भाषा-चयन और भाव के संबंध का विश्लेषण साहित्यिक समझ को गहरा करता है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"दो विद्यार्थियों ने एक ही पाठ का अलग सार लिखा है। दोनों ने कुछ अलग विवरण चुने हैं। शिक्षक किस कसौटी से सार का मूल्यांकन करे?","options":["मूल पाठ से शब्दों का हूबहू मिलान","मुख्य विचार की शुद्धता, आवश्यक विवरणों का चयन और संक्षिप्तता","सार की लंबाई अधिक होना","कठिन शब्दों की संख्या"],"answer":1,"explanation":"अच्छा सार मूल आशय को बनाए रखते हुए आवश्यक विचारों को संक्षेप में प्रस्तुत करता है।"},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner understands individual sentences but misses how pronouns connect ideas across a paragraph. Which activity is most appropriate?","options":["Practise isolated spelling lists","Trace pronoun references and explain how they maintain cohesion","Copy each sentence separately","Memorise punctuation rules only"],"answer":1,"explanation":"Tracking reference words helps learners understand cohesion and links between sentences."},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"A student argues that a character is unreliable, using two contradictory statements from the story. Which teacher prompt deepens the analysis?","options":["How many pages are in the story?","What other evidence supports or challenges your claim, and how does the narrator's perspective matter?","Copy the character's name","List all adjectives"],"answer":1,"explanation":"Evaluating competing evidence and narrative perspective develops critical interpretation."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner's oral presentation has relevant ideas but the audience cannot follow the sequence. Which feedback is most useful?","options":["Speak louder only","Organise ideas with a clear opening, logical sequence and signposting expressions","Use as many difficult words as possible","Memorise every sentence"],"answer":1,"explanation":"Organisation and signposting improve coherence and audience comprehension."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"A teacher wants to assess whether students can evaluate the reliability of online information. Which task is strongest?","options":["Count the hyperlinks","Compare the author's expertise, evidence, date and corroboration across independent sources","Choose the most colourful page","Trust the first search result"],"answer":1,"explanation":"Reliability evaluation requires checking authorship, evidence, currency and independent corroboration."},{"paper":"I","section":"maths","difficulty":"कठिन","q":"एक बच्चा 25% को 25/10 लिखता है। उसकी प्रतिशत की समझ सुधारने के लिए कौन-सा निरूपण सबसे उपयोगी है?","options":["केवल सूत्र लिखवाना","100 बराबर भागों के चित्र में 25 भाग रंगवाकर 25/100 और 1/4 का संबंध दिखाना","25 का पहाड़ा सुनाना","दशमलव हटाकर उत्तर देना"],"answer":1,"explanation":"प्रतिशत का अर्थ प्रति सौ है; दृश्य निरूपण 25/100 = 1/4 को स्पष्ट करता है।"},{"paper":"I","section":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक आयत की लंबाई 10% बढ़ाई और चौड़ाई 10% घटाई जाती है। क्षेत्रफल में क्या परिवर्तन होगा?","options":["कोई परिवर्तन नहीं","1% कमी","1% वृद्धि","10% कमी"],"answer":1,"explanation":"नया क्षेत्रफल गुणक 1.10 × 0.90 = 0.99 है, इसलिए क्षेत्रफल 1% घटता है।"},{"paper":"I","section":"evs","difficulty":"कठिन","q":"बच्चे देखते हैं कि बरसात के बाद स्कूल के पास अधिक मेंढक दिखाई देते हैं। इस अवलोकन को जाँचने का उचित तरीका क्या है?","options":["एक दिन की संख्या से निष्कर्ष निकालना","अलग-अलग दिनों में समान समय और स्थान पर अवलोकन दर्ज कर वर्षा से संबंध की तुलना करना","मेंढकों को पकड़कर कक्षा में रखना","केवल पाठ्यपुस्तक की तस्वीर देखना"],"answer":1,"explanation":"नियमित और तुलनीय अवलोकन से मौसमी बदलाव के संबंध में बेहतर निष्कर्ष निकाला जा सकता है।"},{"paper":"I","section":"evs","difficulty":"अत्यंत चुनौतीपूर्ण","q":"स्कूल में पानी की खपत कम करने की योजना बनानी है। कौन-सा विद्यार्थी प्रोजेक्ट सबसे अधिक प्रमाण-आधारित होगा?","options":["केवल पोस्टर बनाना","एक सप्ताह तक अलग-अलग उपयोगों का मापन, रिसाव की पहचान और उपाय लागू करने के बाद पुनः मापन करना","अनुमान से सबसे बड़ा नल बंद करना","दूसरे स्कूल का आँकड़ा अपना लेना"],"answer":1,"explanation":"पहले और बाद के मापन से हस्तक्षेप का वास्तविक प्रभाव जाँचा जा सकता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"कठिन","q":"किसी कक्षा के पाँच विद्यार्थियों के अंक 20, 22, 24, 26 और 88 हैं। शिक्षक केंद्रीय प्रवृत्ति समझाने के लिए क्या चर्चा कराए?","options":["केवल माध्य बताना","माध्य और माध्यिका दोनों निकालकर अत्यधिक बड़े मान के प्रभाव की तुलना करना","सबसे बड़े अंक को हटा देना","केवल बहुलक बताना"],"answer":1,"explanation":"माध्य 36 है जबकि माध्यिका 24; चरम मान माध्य को अधिक प्रभावित करता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक नक्शे में 1 सेमी दूरी वास्तविक 2.5 किमी दर्शाती है। दो गाँव नक्शे पर 7.2 सेमी दूर हैं। वास्तविक दूरी कितनी होगी?","options":["12 किमी","18 किमी","20 किमी","25 किमी"],"answer":1,"explanation":"7.2 × 2.5 = 18 किमी।"},{"paper":"II","section":"science","group":"maths","difficulty":"कठिन","q":"एक छात्र कहता है कि ध्वनि निर्वात में भी यात्रा कर सकती है। कौन-सा प्रदर्शन इस धारणा की जाँच में सबसे उपयुक्त है?","options":["खुले कमरे में घंटी बजाना","घंटी को निर्वात-पात्र में रखकर हवा निकालने पर ध्वनि की तीव्रता घटने का अवलोकन करना","केवल ध्वनि की परिभाषा लिखना","दीवार पर हाथ रखना"],"answer":1,"explanation":"ध्वनि के प्रसार के लिए माध्यम चाहिए; निर्वात में ध्वनि संचरित नहीं होती।"},{"paper":"II","section":"science","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"विद्यार्थी दावा करता है कि पौधे की जड़ें केवल पौधे को मिट्टी में स्थिर रखती हैं। कौन-सी जाँच इस दावे को चुनौती देगी?","options":["जड़ का रंग देखना","जड़ों द्वारा जल-अवशोषण दिखाने वाला सुरक्षित रंगीन जल प्रयोग और अवलोकन करना","केवल पत्तियों की संख्या गिनना","पौधे को बिना पानी के लंबे समय रखना"],"answer":1,"explanation":"रंगीन जल के संचरण से जड़ों और संवहनी ऊतकों की जल-अवशोषण/परिवहन भूमिका पर चर्चा हो सकती है।"},{"paper":"II","section":"social","group":"social","difficulty":"कठिन","q":"किसी जनगणना तालिका में कुल जनसंख्या बढ़ी है, लेकिन ग्रामीण जनसंख्या का अनुपात घटा है। विद्यार्थी को कौन-सा निष्कर्ष निकालना चाहिए?","options":["ग्रामीण जनसंख्या निश्चित रूप से घट गई","कुल संख्या और प्रतिशत अनुपात अलग बातें हैं; दोनों के वास्तविक मानों की तुलना करनी होगी","शहरी जनसंख्या शून्य हो गई","तालिका गलत है"],"answer":1,"explanation":"अनुपात घटने पर भी कुल जनसंख्या बढ़ने से ग्रामीण आबादी की निरपेक्ष संख्या बढ़ सकती है।"},{"paper":"II","section":"social","group":"social","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक क्षेत्र में औसत आय बढ़ी है, पर अधिकांश परिवारों की आय स्थिर रही। इस स्थिति को समझने के लिए कौन-सा अतिरिक्त विश्लेषण उपयोगी होगा?","options":["केवल औसत आय दोहराना","आय-वितरण, माध्यिका और विभिन्न आय-वर्गों के आँकड़ों की तुलना करना","केवल सबसे अधिक आय देखना","जनसंख्या का नक्शा बनाना"],"answer":1,"explanation":"औसत कुछ अत्यधिक आय वाले समूहों से प्रभावित हो सकता है; वितरण और माध्यिका असमानता को बेहतर दिखाते हैं।"}]);

