window.CTET_QUESTION_BANK = (window.CTET_QUESTION_BANK || []).concat([{"paper":"I","section":"cdp","difficulty":"कठिन","q":"एक बच्चा किसी गणितीय नियम को याद करके सही उत्तर देता है, लेकिन चित्र से वही स्थिति समझाने में असमर्थ है। शिक्षक को किस प्रकार का कार्य देना चाहिए?","options":["और नियम याद करवाना","एक ही अवधारणा को वस्तु, चित्र और प्रतीक के रूप में प्रस्तुत कर संबंध समझाने को कहना","केवल गति से प्रश्न हल करवाना","उत्तर पुस्तिका में सही उत्तर लिख देना"],"answer":1,"explanation":"विभिन्न निरूपणों के बीच संबंध बनाना प्रक्रियात्मक स्मृति से आगे वैचारिक समझ जाँचता है।"},{"paper":"I","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक शिक्षक देखता है कि विद्यार्थी चर्चा में एक-दूसरे के विचार दोहराते हैं, पर प्रमाण नहीं देते। तर्कपूर्ण संवाद विकसित करने के लिए सबसे उपयुक्त हस्तक्षेप क्या है?","options":["चर्चा का समय घटाना","हर दावे के साथ कारण, उदाहरण या प्रमाण देने का नियम और प्रतिवाद का अवसर देना","केवल शिक्षक को बोलने देना","सही उत्तर बोर्ड पर लिख देना"],"answer":1,"explanation":"दावे के समर्थन में प्रमाण और सम्मानजनक प्रतिवाद तर्कपूर्ण संवाद को विकसित करते हैं।"},{"paper":"II","section":"cdp","difficulty":"कठिन","q":"एक विद्यार्थी पाठ्यपुस्तक की परिभाषा सही दोहराता है, पर स्थानीय उदाहरण पर उसे लागू नहीं कर पाता। शिक्षक का अगला कदम क्या होना चाहिए?","options":["परिभाषा फिर से याद करवाना","स्थानीय उदाहरणों के साथ अवधारणा लागू करवाकर सोच की प्रक्रिया पर प्रश्न पूछना","अधिक कठिन परिभाषाएँ देना","उसकी उपलब्धि को पूर्ण मान लेना"],"answer":1,"explanation":"संदर्भ में अनुप्रयोग अवधारणा के हस्तांतरण और वास्तविक समझ का प्रमाण देता है।"},{"paper":"II","section":"cdp","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक विद्यार्थी को कार्य शुरू करने में कठिनाई होती है, लेकिन छोटे चरणों में बाँटने पर वह स्वतंत्र रूप से पूरा कर लेता है। शिक्षक के लिए कौन-सा निष्कर्ष उचित है?","options":["विद्यार्थी कार्य नहीं कर सकता","कार्य की संरचना और क्रमिक सहारा उसकी स्वतंत्र भागीदारी बढ़ाते हैं","उसे हमेशा सरल कार्य ही देना चाहिए","उसकी क्षमता का आकलन संभव नहीं"],"answer":1,"explanation":"कार्य को छोटे चरणों में बाँटना कार्यकारी कौशल और स्व-नियमन के लिए उपयोगी सहारा हो सकता है।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"कठिन","q":"किसी गद्यांश में लेखक ने एक पात्र के व्यवहार का वर्णन किया है, लेकिन उसके उद्देश्य को स्पष्ट नहीं किया। विद्यार्थी से कौन-सा प्रश्न अनुमानात्मक पठन जाँचेगा?","options":["पात्र का नाम क्या है?","पात्र के संवाद और कार्यों से उसके संभावित उद्देश्य का अनुमान लगाकर प्रमाण दो","गद्यांश में कितने वाक्य हैं?","पहला शब्द लिखो"],"answer":1,"explanation":"पात्र के व्यवहार और संवाद से उद्देश्य का अनुमान लगाना निष्कर्षात्मक पठन है।"},{"paper":"I","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक लेख में लेखक ने दो विकल्पों की तुलना की है, पर केवल एक विकल्प के लाभ विस्तार से बताए हैं। आलोचनात्मक पठन के लिए विद्यार्थी को क्या जाँचना चाहिए?","options":["लेख की लंबाई","क्या दोनों विकल्पों के प्रमाण समान रूप से प्रस्तुत हैं और कौन-सी जानकारी छूटी है","केवल कठिन शब्द","लेखक की लिखावट"],"answer":1,"explanation":"चयनात्मक प्रस्तुति और छूटी हुई जानकारी पहचानना आलोचनात्मक पठन का हिस्सा है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"कठिन","q":"विद्यार्थी किसी कहानी का सार लिखते समय अपने विचार भी जोड़ देता है। शिक्षक कौन-सा निर्देश देगा?","options":["सार को और लंबा करो","मूल पाठ के मुख्य विचारों को अपने शब्दों में लिखो और निजी टिप्पणी अलग रखो","केवल संवाद लिखो","कहानी की नकल करो"],"answer":1,"explanation":"सार में मूल पाठ का आशय संक्षेप में आता है; निजी मूल्यांकन अलग रखा जाता है।"},{"paper":"II","section":"language","language":"हिंदी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक पाठ में व्यंग्य का प्रयोग है। विद्यार्थी केवल शाब्दिक अर्थ बताता है। शिक्षक किस गतिविधि से व्यंग्यार्थ स्पष्ट करेगा?","options":["शब्दों की वर्णमाला लिखवाना","कथन, प्रसंग और वास्तविक स्थिति की तुलना कर निहित अर्थ पर चर्चा करना","पाठ का श्रुतलेख","केवल कठिन शब्दार्थ देना"],"answer":1,"explanation":"व्यंग्य समझने के लिए शाब्दिक कथन और संदर्भ में निहित अर्थ की तुलना करनी होती है।"},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A learner can identify facts in a text but treats an author's opinion as a fact. Which task is most useful?","options":["Copy the text","Highlight factual claims and opinions, then identify the evidence used for each","Memorise the title","Practise handwriting"],"answer":1,"explanation":"Distinguishing fact, opinion and supporting evidence strengthens critical reading."},{"paper":"I","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"A learner gives a plausible inference about a poem but cannot connect it to the imagery. What should the teacher ask?","options":["How many lines are in the poem?","Which images or word choices led you to that interpretation?","Copy the poem twice","Name the poet only"],"answer":1,"explanation":"Interpretations should be linked to textual features such as imagery and diction."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"कठिन","q":"A student writes a report with accurate details but no clear sequence. Which scaffold best supports revision?","options":["A list of difficult words","A timeline or outline to organise events before rewriting","A spelling test","A longer passage to copy"],"answer":1,"explanation":"Planning with a timeline or outline helps organise information coherently."},{"paper":"II","section":"language","language":"अंग्रेज़ी","difficulty":"अत्यंत चुनौतीपूर्ण","q":"Students compare a news report with a social media post about the same event. Which prompt best develops critical media literacy?","options":["Which one is shorter?","How do source, evidence, wording and omissions shape the reader's understanding?","Which has more pictures?","Copy both headlines"],"answer":1,"explanation":"Critical media literacy examines source credibility, evidence, framing and omission."},{"paper":"I","section":"maths","difficulty":"कठिन","q":"एक बच्चा 0.5 + 0.25 = 0.30 लिखता है। शिक्षक को कौन-सा तरीका अपनाना चाहिए?","options":["दशमलव के बाद के अंक जोड़ने का नियम रटवाना","दशमलवों को समान स्थान-मूल्य तक लिखकर 0.50 + 0.25 को संख्या रेखा या मॉडल से जोड़ना","उत्तर सीधे बता देना","दशमलव को हटाकर जोड़ना"],"answer":1,"explanation":"0.5 को 0.50 लिखने से सौवें स्थान का अर्थ स्पष्ट होता है और योग 0.75 आता है।"},{"paper":"I","section":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक आयताकार खेत की लंबाई 15% बढ़ती है और चौड़ाई 15% घटती है। क्षेत्रफल में कुल परिवर्तन क्या होगा?","options":["अपरिवर्तित","2.25% कमी","2.25% वृद्धि","15% कमी"],"answer":1,"explanation":"नया क्षेत्रफल गुणक 1.15 × 0.85 = 0.9775 है, इसलिए 2.25% कमी होती है।"},{"paper":"I","section":"evs","difficulty":"कठिन","q":"बच्चे दावा करते हैं कि पौधे की वृद्धि के लिए खाद ही सबसे जरूरी कारक है। इस दावे की जाँच के लिए शिक्षक क्या कराए?","options":["सभी पौधों को अलग-अलग परिस्थितियों में रखना","समान पौधों में नियंत्रित ढंग से एक कारक बदलकर अन्य स्थितियाँ समान रखना और वृद्धि दर्ज करना","एक पौधे को देखकर निष्कर्ष निकालना","केवल खाद के प्रकार याद करवाना"],"answer":1,"explanation":"नियंत्रित तुलना से किसी एक कारक के प्रभाव को अन्य कारकों से अलग समझा जा सकता है।"},{"paper":"I","section":"evs","difficulty":"अत्यंत चुनौतीपूर्ण","q":"स्कूल में प्लास्टिक उपयोग घटाने की पहल के प्रभाव का आकलन कैसे किया जाए?","options":["केवल पोस्टर की संख्या गिनना","पहल से पहले और बाद में प्लास्टिक कचरे की मात्रा और स्रोतों का समान अवधि में रिकॉर्ड रखना","विद्यार्थियों से अनुमान पूछना","केवल एक दिन का निरीक्षण करना"],"answer":1,"explanation":"पूर्व और पश्चात समान अवधि के आँकड़े पहल के प्रभाव का तुलनात्मक प्रमाण देते हैं।"},{"paper":"II","section":"maths","group":"maths","difficulty":"कठिन","q":"एक विद्यार्थी कहता है कि 2:3 और 4:6 अलग अनुपात हैं क्योंकि संख्याएँ अलग हैं। कौन-सा उदाहरण उसकी समझ सुधारेगा?","options":["केवल अनुपात की परिभाषा","दोनों अनुपातों को समान वस्तुओं के समूह या भिन्न के रूप में दिखाकर समतुल्यता समझाना","अनुपात के अंक जोड़ना","एक अनुपात को गलत घोषित करना"],"answer":1,"explanation":"2/3 और 4/6 समतुल्य हैं; दृश्य समूह या भिन्न से यह स्पष्ट होता है।"},{"paper":"II","section":"maths","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"एक वस्तु पर पहले 10% और फिर 20% छूट दी जाती है। कुल प्रभावी छूट कितनी है?","options":["30%","28%","32%","18%"],"answer":1,"explanation":"₹100 पर पहले ₹90 और फिर ₹72 शेष रहता है; प्रभावी छूट 28% है।"},{"paper":"II","section":"science","group":"maths","difficulty":"कठिन","q":"एक विद्यार्थी कहता है कि भारी वस्तु हमेशा पानी में डूबती है। कौन-सा उदाहरण इस सामान्यीकरण की जाँच करेगा?","options":["एक पत्थर को पानी में डालना","बड़े आकार के लकड़ी के लट्ठे और छोटे धातु के टुकड़े के व्यवहार की तुलना कर घनत्व पर चर्चा करना","केवल वस्तुओं का भार लिखना","पानी का रंग देखना"],"answer":1,"explanation":"तैरना-डूबना केवल कुल भार पर नहीं, औसत घनत्व और उत्प्लावन पर निर्भर करता है।"},{"paper":"II","section":"science","group":"maths","difficulty":"अत्यंत चुनौतीपूर्ण","q":"दो समान बीजों को अलग परिस्थितियों में रखा गया: एक को पानी और हवा मिली, दूसरे को पानी नहीं मिला। प्रयोग से कौन-सा निष्कर्ष सीमित रूप से निकाला जा सकता है?","options":["बीजों को केवल प्रकाश चाहिए","इस तुलना में पानी की उपलब्धता अंकुरण को प्रभावित कर सकती है; अन्य कारकों को नियंत्रित रखना होगा","सभी बीज एक ही समय अंकुरित होंगे","मिट्टी का कोई महत्व नहीं"],"answer":1,"explanation":"निष्कर्ष को जाँचे गए चर तक सीमित रखना चाहिए और तापमान, बीज की गुणवत्ता जैसे कारक नियंत्रित करने चाहिए।"},{"paper":"II","section":"social","group":"social","difficulty":"कठिन","q":"किसी पुराने नक्शे में आज की सीमा-रेखाएँ नहीं दिखाई देतीं। इतिहास और भूगोल के विद्यार्थी को क्या करना चाहिए?","options":["नक्शे को गलत घोषित करना","नक्शे की तिथि, उद्देश्य, पैमाना और उस समय की राजनीतिक सीमाओं के संदर्भ में व्याख्या करना","केवल वर्तमान सीमा बनाना","नक्शे के रंग याद करना"],"answer":1,"explanation":"ऐतिहासिक मानचित्र को उसके समय, उद्देश्य और मानचित्रण परंपरा के संदर्भ में पढ़ना चाहिए।"},{"paper":"II","section":"social","group":"social","difficulty":"अत्यंत चुनौतीपूर्ण","q":"किसी शहर में औसत वर्षा स्थिर है, लेकिन कुछ वर्षों में बाढ़ अधिक आई है। इस अंतर को समझने के लिए कौन-से आँकड़े उपयोगी होंगे?","options":["केवल वार्षिक औसत वर्षा","अल्प अवधि की तीव्र वर्षा, भूमि उपयोग, जल निकासी और नदी-स्तर के आँकड़ों की तुलना","केवल शहर की जनसंख्या","केवल तापमान"],"answer":1,"explanation":"बाढ़ का जोखिम औसत वर्षा के अलावा तीव्र वर्षा, भूमि उपयोग और जल निकासी पर निर्भर करता है।"}]);

